<script setup lang="ts">
import PageLink from './components/PageLink.vue';
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';
import {auth,hasWorkspace,login,logout} from './stores/auth';import {notices,dismiss} from './stores/notices';import Icon from './components/Icon.vue';import {usePage} from './lib/pages';
const route=useRoute(),menu=ref(false),theme=ref('dark');const navigation=usePage('agl','navigation');const home=usePage('agl','home');const authEntry=computed(()=>route.path==='/profile/'&&!auth.user);const inWorkspace=computed(()=>route.path.startsWith('/workspace/'));
try{theme.value=localStorage.getItem('agl.theme')||(matchMedia('(prefers-color-scheme:light)').matches?'light':'dark');}catch{}
function applyTheme(){document.documentElement.dataset.theme=theme.value;try{localStorage.setItem('agl.theme',theme.value);}catch{}}
function toggleTheme(){theme.value=theme.value==='dark'?'light':'dark';applyTheme();}applyTheme();watch(()=>route.fullPath,()=>menu.value=false);
function escape(event:KeyboardEvent){if(event.key==='Escape')menu.value=false;}window.addEventListener('keydown',escape);onBeforeUnmount(()=>window.removeEventListener('keydown',escape));
</script>
<template><div :class="inWorkspace?'workspace-mode':(authEntry?'public-site auth-entry':'public-site')"><a class="skip-link" href="#main">К содержимому</a>
<header v-if="!inWorkspace" class="site-header"><div class="container header-inner"><PageLink to="/" class="brand-v2" aria-label="Alex Game Lab — главная"><span class="brand-symbol" aria-hidden="true">a<span>g</span>l</span><span>{{navigation.title}}</span></PageLink><nav v-if="!authEntry" class="desktop-nav" aria-label="Главная навигация"><a v-for="link in navigation.links" :key="link.url" :href="link.url" :aria-current="route.path===link.url?'page':undefined"><Icon :name="link.url.includes('projects')?'projects':link.url.includes('news')?'news':'users'" :size="16"/>{{link.label}}</a><PageLink v-if="hasWorkspace" to="/workspace/">Кабинет ↗</PageLink></nav><div class="header-actions"><button class="icon-button" :aria-label="theme==='dark'?'Включить светлую тему':'Включить тёмную тему'" @click="toggleTheme"><Icon :name="theme==='dark'?'sun':'moon'" :size="19"/></button><PageLink v-if="auth.user" to="/profile/" class="header-login">AGL ID ↗</PageLink><button v-else-if="!authEntry" class="header-login" @click="login()">Войти ↗</button><button v-if="!authEntry" class="icon-button menu-toggle" :aria-expanded="menu" aria-controls="mobile-menu" :aria-label="menu?'Закрыть меню':'Открыть меню'" @click="menu=!menu"><Icon :name="menu?'close':'menu'"/></button></div></div><nav v-if="menu" id="mobile-menu" class="mobile-nav container" aria-label="Мобильная навигация"><a v-for="link in navigation.links" :key="link.url" :href="link.url"><span><Icon :name="link.url.includes('projects')?'projects':link.url.includes('news')?'news':'users'" :size="21"/>{{link.label}}</span><Icon name="right" :size="18"/></a><PageLink to="/profile/">Профиль AGL ID ↗</PageLink><PageLink v-if="hasWorkspace" to="/workspace/">Рабочее пространство ↗</PageLink></nav></header>
<header v-else class="workspace-topbar"><PageLink to="/" class="workspace-wordmark"><span class="brand-symbol" aria-hidden="true">agl</span><strong>AGL</strong><span>Рабочее пространство</span></PageLink><div class="button-row"><button class="icon-button" :aria-label="theme==='dark'?'Включить светлую тему':'Включить тёмную тему'" @click="toggleTheme"><Icon :name="theme==='dark'?'sun':'moon'"/></button><PageLink to="/profile/" class="workspace-account"><Icon name="user"/><span>{{auth.profile?.display_name||'Профиль'}}</span></PageLink></div></header>
<main id="main" tabindex="-1"><RouterView/></main>
<footer v-if="!inWorkspace&&!authEntry" class="site-footer"><div class="container"><div class="footer-v2"><div><p class="eyebrow">{{navigation.title}}</p><span class="footer-mark" aria-hidden="true">AGL</span><p>{{navigation.footer_note}}</p></div><nav aria-label="Навигация в подвале"><a v-for="link in navigation.links" :key="link.url" :href="link.url"><span><Icon :name="link.url.includes('projects')?'projects':link.url.includes('news')?'news':'users'" :size="21"/>{{link.label}}</span><Icon name="right" :size="18"/></a><PageLink to="/profile/">AGL ID ↗</PageLink><PageLink v-if="hasWorkspace" to="/workspace/">Рабочее пространство ↗</PageLink></nav><div class="footer-contact"><p class="eyebrow">{{navigation.sections[0]?.title||'НА СВЯЗИ'}}</p><a :href="home.channel_url">{{home.channel_label}} ↗</a><template v-for="(block,index) in navigation.sections" :key="index"><p v-if="index" class="eyebrow">{{block.title}}</p><p v-if="block.body">{{block.body}}</p><template v-for="link in block.links" :key="link.url"><a v-if="link.url!==home.channel_url" :href="link.url">{{link.label}} ↗</a></template></template></div></div><div class="footer-bottom"><span>© {{new Date().getFullYear()}} Alex Game Lab</span><a href="/privacy/">Конфиденциальность</a><button v-if="auth.user" class="text-button" @click="logout">Выйти</button><a href="#top">Наверх ↑</a></div></div></footer>
<div class="toast-stack" aria-live="polite"><div v-for="notice in notices" :key="notice.id" class="toast" :class="{error:notice.error}" :role="notice.error?'alert':'status'"><Icon :name="notice.error?'warning':'check'" :size="18"/><span>{{notice.text}}</span><button class="icon-button" aria-label="Закрыть уведомление" @click="dismiss(notice.id)"><Icon name="close" :size="16"/></button></div></div></div></template>
